    26→  const handleLogin = async () => {
    27→    setPhoneError(''); setPwError('');
    28→    let hasErr = false;
    29→    if (!phone.trim()) { setPhoneError('Phone number is required'); hasErr = true; }
    30→    if (!password) { setPwError('Password is required'); hasErr = true; }
    31→    if (hasErr) return;
    32→
    33→    setLoading(true);
    34→    try {
    35→      const { data } = await api.post('/auth/login', {
    36→        phone_number: phone.replace(/\s/g, ''),
    37→        password,
    38→      });
    39→      await TokenStorage.setTokens(data.access_token, data.refresh_token);
    40→      setUser(data.user);
    41→      router.replace('/(tabs)');
    42→    } catch (err) {
    43→      const msg = err.response?.data?.error || 'Login failed. Please try again.';
    44→      if (msg.toLowerCase().includes('credentials') || msg.toLowerCase().includes('password') || msg.toLowerCase().includes('phone')) {
    45→        setPhoneError('Incorrect phone number or password');
    46→      } else {
    47→        Alert.alert('Login Failed', msg);
    48→      }
    49→    } finally {
    50→      setLoading(false);
    51→    }
    52→  };
    53→
    54→  return (
    55→    <View style={styles.screen}>
    56→      <LinearGradient colors={['#075E54', '#128C7E']} style={styles.header}>
    57→        <SafeAreaView>
    58→          <View style={styles.logoRow}>
