    68→      </LinearGradient>
    69→
    70→      <KeyboardAvoidingView
    71→        style={{ flex: 1 }}
    72→        behavior={Platform.OS === 'ios' ? 'padding' : undefined}
    73→      >
    74→        <ScrollView
    75→          contentContainerStyle={styles.formContainer}
    76→          keyboardShouldPersistTaps="handled"
    77→        >
    78→          <Text style={styles.title}>Welcome back</Text>
    79→          <Text style={styles.subtitle}>Sign in to continue your conversations</Text>
    80→
    81→          <View style={styles.field}>
    82→            <Text style={styles.label}>Phone Number</Text>
    83→            <PhoneInput
    84→              value={phone}
    85→              onChange={setPhone}
    86→              error={phoneError}
    87→            />
    88→            {phoneError ? <Text style={styles.errorText}>{phoneError}</Text> : null}
    89→          </View>
    90→
    91→          <View style={styles.field}>
    92→            <Text style={styles.label}>Password</Text>
    93→            <View style={[styles.pwContainer, pwError && styles.inputError]}>
    94→              <Ionicons name="lock-closed" size={18} color={COLORS.accent} style={styles.pwIcon} />
    95→              <TextInput
    96→                style={styles.pwInput}
    97→                value={password}
    98→                onChangeText={t => { setPassword(t); setPwError(''); }}
    99→                placeholder="Enter your password"
   100→                placeholderTextColor={COLORS.gray}
   101→                secureTextEntry={!showPw}
   102→                autoCapitalize="none"
   103→                returnKeyType="done"
   104→                onSubmitEditing={handleLogin}
   105→              />
   106→              <TouchableOpacity onPress={() => setShowPw(v => !v)} style={styles.eyeBtn}>
   107→                <Ionicons name={showPw ? 'eye-off' : 'eye'} size={18} color={COLORS.gray} />
   108→              </TouchableOpacity>
   109→            </View>
   110→            {pwError ? <Text style={styles.errorText}>{pwError}</Text> : null}
   111→          </View>
   112→
   113→          <TouchableOpacity
   114→            style={[styles.loginBtn, loading && styles.loginBtnDisabled]}
   115→            onPress={handleLogin}
   116→            disabled={loading}
   117→            activeOpacity={0.85}
   118→          >
   119→            {loading ? (
   120→              <ActivityIndicator color="#fff" />
   121→            ) : (
   122→              <>
   123→                <Text style={styles.loginBtnText}>Sign In</Text>
   124→                <Ionicons name="arrow-forward" size={18} color="#fff" />
   125→              </>
   126→            )}
   127→          </TouchableOpacity>
   128→
   129→          <View style={styles.dividerRow}>
   130→            <View style={styles.divider} />
   131→            <Text style={styles.orText}>or</Text>
   132→            <View style={styles.divider} />
   133→          </View>
   134→
   135→          <TouchableOpacity
   136→            style={styles.signupBtn}
   137→            onPress={() => router.push('/signup')}
   138→            activeOpacity={0.8}
   139→          >
