    16→const TWO_DAYS_MS = 2 * 24 * 60 * 60 * 1000;
    17→
    18→function needsConfirmation(user) {
    19→  if (!user) return false;
    20→  if (user.account_confirmed_at) return false;
    21→  const createdAt = new Date(user.created_at).getTime();
    22→  return Date.now() - createdAt >= TWO_DAYS_MS;
    23→}
    24→
    25→function ProtectedRoute({ user, children }) {
    26→  if (!user) return <Navigate to="/login" replace />;
    27→  if (needsConfirmation(user)) return <Navigate to="/verify-account" replace />;
    28→  return children;
    29→}
    30→
    31→function App() {
    32→  const { user, setUser, setLoading, isAuthenticated } = useAuthStore();
    33→  const [initializing, setInitializing] = useState(true);
    34→
    35→  useEffect(() => {
    36→    const initializeApp = async () => {
    37→      try {
    38→        const token = localStorage.getItem('access_token');
    39→        if (token) {
    40→          const response = await api.get('/auth/user');
    41→          setUser(response.data);
    42→          // Initialize push notifications after user is loaded
    43→          registerServiceWorker().then(() => {
    44→            subscribeToPush().catch(() => {});
    45→          }).catch(() => {});
    46→        }
    47→      } catch (error) {
    48→        console.error('Failed to load user:', error);
    49→        localStorage.removeItem('access_token');
    50→        localStorage.removeItem('refresh_token');
    51→      } finally {
    52→        setLoading(false);
    53→        setInitializing(false);
    54→      }
    55→    };
    56→    initializeApp();
    57→
    58→    // Listen for push notification click events from service worker
    59→    listenForPushMessages((msg) => {
    60→      if (msg?.url) window.location.href = msg.url;
    61→    });
    62→  }, [setUser, setLoading]);
    63→
    64→  if (initializing) {
    65→    return (
    66→      <div className="flex items-center justify-center h-screen bg-[#f0f2f5]">
    67→        <div className="text-center">
