import AsyncStorage from '@react-native-async-storage/async-storage';

const KEYS = {
  CONTACTS: 'vc_contacts',
  PHONE_CONTACTS: 'vc_phone_contacts',
  MESSAGES: 'vc_messages_',
  PROFILE: 'vc_profile',
  SETTINGS: 'vc_settings',
  CALL_HISTORY: 'vc_call_history',
  OFFLINE_QUEUE: 'vc_offline_queue',
};

const MAX_MESSAGES_PER_CHAT = 200;

async function safeGet(key) {
  try {
    const raw = await AsyncStorage.getItem(key);
    return raw ? JSON.parse(raw) : null;
  } catch {
    return null;
  }
}

async function safeSet(key, value) {
  try {
    await AsyncStorage.setItem(key, JSON.stringify(value));
  } catch {}
}

export const Cache = {
  // Contacts
  getContacts: () => safeGet(KEYS.CONTACTS),
  setContacts: (contacts) => safeSet(KEYS.CONTACTS, contacts),

  // Phone contacts (synced from device)
  getPhoneContacts: () => safeGet(KEYS.PHONE_CONTACTS),
  setPhoneContacts: (data) => safeSet(KEYS.PHONE_CONTACTS, data),

  // Messages per chat
  getMessages: (chatId) => safeGet(KEYS.MESSAGES + chatId),
  setMessages: async (chatId, messages) => {
    const trimmed = Array.isArray(messages)
      ? messages.slice(-MAX_MESSAGES_PER_CHAT)
      : messages;
    await safeSet(KEYS.MESSAGES + chatId, trimmed);
  },
  appendMessage: async (chatId, message) => {
    const existing = (await safeGet(KEYS.MESSAGES + chatId)) || [];
    const updated = [...existing, message].slice(-MAX_MESSAGES_PER_CHAT);
    await safeSet(KEYS.MESSAGES + chatId, updated);
  },

  // Profile
  getProfile: () => safeGet(KEYS.PROFILE),
  setProfile: (profile) => safeSet(KEYS.PROFILE, profile),

  // Settings
  getSettings: () => safeGet(KEYS.SETTINGS),
  setSettings: (settings) => safeSet(KEYS.SETTINGS, settings),

  // Call history
  getCallHistory: () => safeGet(KEYS.CALL_HISTORY),
  setCallHistory: (calls) => safeSet(KEYS.CALL_HISTORY, calls),

  // Offline message queue
  getOfflineQueue: async () => (await safeGet(KEYS.OFFLINE_QUEUE)) || [],
  addToOfflineQueue: async (item) => {
    const queue = (await safeGet(KEYS.OFFLINE_QUEUE)) || [];
    const updated = [...queue, { ...item, queuedAt: Date.now(), id: Math.random().toString(36).slice(2) }];
    await safeSet(KEYS.OFFLINE_QUEUE, updated);
    return updated;
  },
  removeFromOfflineQueue: async (itemId) => {
    const queue = (await safeGet(KEYS.OFFLINE_QUEUE)) || [];
    const updated = queue.filter(i => i.id !== itemId);
    await safeSet(KEYS.OFFLINE_QUEUE, updated);
    return updated;
  },
  clearOfflineQueue: () => safeSet(KEYS.OFFLINE_QUEUE, []),

  // Clear all app cache (not auth tokens)
  clearAll: async () => {
    try {
      const keys = await AsyncStorage.getAllKeys();
      const vcKeys = keys.filter(k => k.startsWith('vc_'));
      await AsyncStorage.multiRemove(vcKeys);
    } catch {}
  },
};

import * as Contacts from 'expo-contacts';
import { Cache } from './cache';
import api from './api';

/**
 * Normalize a phone number to E.164-ish format for matching.
 * Strips spaces, dashes, parentheses, dots.
 */
function normalizePhone(phone) {
  return phone.replace(/[\s\-().]/g, '');
}

/**
 * Request contacts permission and fetch all phone contacts from the device.
 * Returns { granted: bool, contacts: Contacts[] }
 */
export async function fetchDeviceContacts() {
  const { status } = await Contacts.requestPermissionsAsync();
  if (status !== 'granted') {
    return { granted: false, contacts: [] };
  }
  const { data } = await Contacts.getContactsAsync({
    fields: [
      Contacts.Fields.Name,
      Contacts.Fields.PhoneNumbers,
      Contacts.Fields.Image,
    ],
    sort: Contacts.SortTypes.FirstName,
  });
  return { granted: true, contacts: data || [] };
}

/**
 * Extract all unique phone numbers from device contacts,
 * returning an array of { name, phoneNumber, rawContact }.
 */
export function extractPhoneNumbers(deviceContacts) {
  const seen = new Set();
  const result = [];
  for (const contact of deviceContacts) {
    if (!contact.phoneNumbers?.length) continue;
    const name = contact.name || 'Unknown';
    for (const ph of contact.phoneNumbers) {
      const raw = ph.number || '';
      const norm = normalizePhone(raw);
      if (!norm || seen.has(norm)) continue;
      seen.add(norm);
      result.push({ name, phoneNumber: raw, normalizedPhone: norm, rawContact: contact });
    }
  }
  return result;
}

/**
 * Full sync: fetch device contacts → send to backend → return
 * { granted, vipchatContacts, phoneOnlyContacts, lastSynced }
 *
 * Results are cached in AsyncStorage so they're available offline.
 */
export async function syncPhoneContacts({ force = false } = {}) {
  // Return cached result if recent (within 30 minutes) unless forced
  if (!force) {
    const cached = await Cache.getPhoneContacts();
    if (cached && Date.now() - (cached.lastSynced || 0) < 30 * 60 * 1000) {
      return cached;
    }
  }

  const { granted, contacts: deviceContacts } = await fetchDeviceContacts();
  if (!granted) {
    return { granted: false, vipchatContacts: [], phoneOnlyContacts: [], lastSynced: null };
  }

  const entries = extractPhoneNumbers(deviceContacts);
  if (entries.length === 0) {
    return { granted: true, vipchatContacts: [], phoneOnlyContacts: [], lastSynced: Date.now() };
  }

  // Send all phone numbers to backend
  const phoneNumbers = entries.map(e => e.phoneNumber);
  let registered = [];
  let unregistered = [];

  try {
    const { data } = await api.post('/contacts/sync-phone', { phone_numbers: phoneNumbers });
    registered = data.registered || [];
    unregistered = data.unregistered || [];
  } catch (err) {
    console.warn('[phoneContacts] sync failed:', err.message);
    // Use cached data if available
    const cached = await Cache.getPhoneContacts();
    if (cached) return cached;
    return { granted: true, vipchatContacts: [], phoneOnlyContacts: entries, lastSynced: null };
  }

  // Build vipchatContacts with device name overlay
  const registeredPhones = new Set(registered.map(r => normalizePhone(r.phone_number)));
  const vipchatContacts = registered.map(r => {
    // Find the device contact name for this phone
    const match = entries.find(e => normalizePhone(e.phoneNumber) === normalizePhone(r.phone_number));
    return {
      ...r,
      contact_name: match?.name || r.full_name,
      contact_user_id: r.id,
    };
  });

  // Phone-only contacts: on device but not on VipChat
  const phoneOnlyContacts = entries
    .filter(e => !registeredPhones.has(e.normalizedPhone))
    .map(e => ({ name: e.name, phoneNumber: e.phoneNumber }));

  const result = {
    granted: true,
    vipchatContacts,
    phoneOnlyContacts,
    lastSynced: Date.now(),
  };

  await Cache.setPhoneContacts(result);
  return result;
}

import { useState, useEffect } from 'react';
import NetInfo from '@react-native-community/netinfo';

/**
 * Returns current network status.
 * { isOnline: bool, connectionType: string }
 */
export function useNetworkStatus() {
  const [status, setStatus] = useState({ isOnline: true, connectionType: 'unknown' });

  useEffect(() => {
    // Get initial state
    NetInfo.fetch().then(state => {
      setStatus({
        isOnline: state.isConnected && state.isInternetReachable !== false,
        connectionType: state.type,
      });
    });

    // Subscribe to changes
    const unsubscribe = NetInfo.addEventListener(state => {
      setStatus({
        isOnline: state.isConnected && state.isInternetReachable !== false,
        connectionType: state.type,
      });
    });

    return unsubscribe;
  }, []);

  return status;
}

