    15→async function safeGet(key) {
    16→  try {
    17→    const raw = await AsyncStorage.getItem(key);
    18→    return raw ? JSON.parse(raw) : null;
    19→  } catch {
    20→    return null;
    21→  }
    22→}
    23→
    24→async function safeSet(key, value) {
    25→  try {
    26→    await AsyncStorage.setItem(key, JSON.stringify(value));
    27→  } catch {}
    28→}
    29→
    30→export const Cache = {
    31→  // Contacts
    32→  getContacts: () => safeGet(KEYS.CONTACTS),
    33→  setContacts: (contacts) => safeSet(KEYS.CONTACTS, contacts),
    34→
    35→  // Phone contacts (synced from device)
    36→  getPhoneContacts: () => safeGet(KEYS.PHONE_CONTACTS),
    37→  setPhoneContacts: (data) => safeSet(KEYS.PHONE_CONTACTS, data),
