    39→  // Messages per chat
    40→  getMessages: (chatId) => safeGet(KEYS.MESSAGES + chatId),
    41→  setMessages: async (chatId, messages) => {
    42→    const trimmed = Array.isArray(messages)
    43→      ? messages.slice(-MAX_MESSAGES_PER_CHAT)
    44→      : messages;
    45→    await safeSet(KEYS.MESSAGES + chatId, trimmed);
    46→  },
    47→  appendMessage: async (chatId, message) => {
    48→    const existing = (await safeGet(KEYS.MESSAGES + chatId)) || [];
    49→    const updated = [...existing, message].slice(-MAX_MESSAGES_PER_CHAT);
    50→    await safeSet(KEYS.MESSAGES + chatId, updated);
    51→  },
    52→
    53→  // Profile
    54→  getProfile: () => safeGet(KEYS.PROFILE),
    55→  setProfile: (profile) => safeSet(KEYS.PROFILE, profile),
    56→
    57→  // Settings
    58→  getSettings: () => safeGet(KEYS.SETTINGS),
    59→  setSettings: (settings) => safeSet(KEYS.SETTINGS, settings),
