    61→  // Call history
    62→  getCallHistory: () => safeGet(KEYS.CALL_HISTORY),
    63→  setCallHistory: (calls) => safeSet(KEYS.CALL_HISTORY, calls),
    64→
    65→  // Offline message queue
    66→  getOfflineQueue: async () => (await safeGet(KEYS.OFFLINE_QUEUE)) || [],
    67→  addToOfflineQueue: async (item) => {
    68→    const queue = (await safeGet(KEYS.OFFLINE_QUEUE)) || [];
    69→    const updated = [...queue, { ...item, queuedAt: Date.now(), id: Math.random().toString(36).slice(2) }];
    70→    await safeSet(KEYS.OFFLINE_QUEUE, updated);
    71→    return updated;
    72→  },
